import{_ as r,a0 as s,w as p,s as i,ao as d,I as a,x as t,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"ls命令的20個實用範例 | LCTT x X-CMD","titleTemplate":false,"description":"ls命令的20個實用範例 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ls命令的20個實用範例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ls命令的20個實用範例 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/20 Linux ls Command Examples to Display the Entries of Directory","title":"ls命令的20個實用範例","tag":"201402","desc":""},"relativePath":"201402/20 Linux ls Command Examples to Display the Entries of Directory.md","filePath":"[post].md"}'),c={name:"201402/20 Linux ls Command Examples to Display the Entries of Directory.md"};function h(g,e,m,x,_,u){const o=s("Link");return p(),i("div",null,[e[11]||(e[11]=d(`<h1 id="ls命令的20個實用範例" tabindex="-1">ls命令的20個實用範例 <a class="header-anchor" href="#ls命令的20個實用範例" aria-label="Permalink to “ls命令的20個實用範例”">​</a></h1><p>Linux中一個基本命令是ls。沒有這個命令，我們會在瀏覽目錄條目時會遇到困難。這個命令必須被每個學習Linux的人知道。</p><h3 id="ls是什麼" tabindex="-1">ls是什麼 <a class="header-anchor" href="#ls是什麼" aria-label="Permalink to “ls是什麼”">​</a></h3><p>ls命令用於列出文件和目錄。默認上，他會列出當前目錄的內容。帶上參數後，我們可以用ls做更多的事情。這裏是一些在日常操作中使用到的ls用法的示例。</p><h4 id="_1-不帶參數運行ls" tabindex="-1">1. 不帶參數運行ls <a class="header-anchor" href="#_1-不帶參數運行ls" aria-label="Permalink to “1. 不帶參數運行ls”">​</a></h4><p>不帶參數運行ls會只列出文件或者目錄。看不到其他信息輸出（譯註：有時候你發現無參數的ls命令和這裏描述的不同，那有可能是你的ls命令實際上帶參數的ls別名）。</p><pre><code>$ ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls.png" alt=""></p><h4 id="_2-使用長清單模式" tabindex="-1">2. 使用長清單模式 <a class="header-anchor" href="#_2-使用長清單模式" aria-label="Permalink to “2. 使用長清單模式”">​</a></h4><p>使用-l字符(小寫L字符),會顯示當前目錄內容的長列表。在接下來的例子中，我們會結合-l參數(這個參數經常使用)來得到更好的結果。</p><pre><code>$ ls -l
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_l.png" alt=""></p><p>這裏是如何讀取輸出 :</p><ul><li><p><strong>第1列</strong></p><ul><li><p>第一個字母<strong>d</strong>意味着內容是目錄或者文件。在上面的截圖中，Desktop、 Documents、 Downloads 和 lynis-1.3.8是目錄。如果是&#39;-&#39;(<strong>減號</strong>)，這意味着它的內容是文件。當它是l(<strong>小寫l字符</strong>)，意味這內容是鏈接文件。</p></li><li><p>下面的9個字符是關於文件權限。<strong>前3個rwx</strong>字符是文件的擁有者的權限，<strong>第二組3rwx</strong>是文件的所有組的權限，<strong>最後的rwx</strong>是對其他人訪問文件的權限。</p></li></ul></li><li><p><strong>第2列</strong> 這行告訴我們有多少鏈接指向這個文件。</p></li><li><p><strong>第3列</strong> 這行告訴我們誰是這個文件/文件夾的所有者。</p></li><li><p><strong>第4列</strong> 這行告訴我們誰是這個文件/文件夾的所有組。</p></li><li><p><strong>第5列</strong> 這行告訴我們這個文件/文件夾的以字節為單位的大小。 目錄的大小總是4096字節。</p></li><li><p><strong>第6列</strong> 這告訴我們文件最後的修改時間。</p></li><li><p><strong>第7列</strong> 這告訴我們文件名或者目錄名。</p></li></ul><h4 id="_3-顯示文件大小" tabindex="-1">3. 顯示文件大小 <a class="header-anchor" href="#_3-顯示文件大小" aria-label="Permalink to “3. 顯示文件大小”">​</a></h4><p>以字節為單位看大小可能會不方便。6.5M讀起來比6727680字節更簡單。要這麼做，我們可以使用-h與<strong>-l</strong>結合的參數。<strong>-h參數意味着便於人識別</strong>。</p><pre><code>$ ls -lh
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_lh1.png" alt=""></p><p>另外一個可以這麼做的參數是<strong>--si</strong>。這個參數和-h參數類似，但是<strong>-si以1000為單位，而-h以1024為單位</strong>。</p><pre><code>$ ls -si
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_si.png" alt=""></p><h4 id="_4-排序文件大小" tabindex="-1">4. 排序文件大小 <a class="header-anchor" href="#_4-排序文件大小" aria-label="Permalink to “4. 排序文件大小”">​</a></h4><p>在我們可以顯示文件大小之後，我們希望以文件大小排序。我們可以使用-S參數來這麼做。這列表會從大到校排序。</p><pre><code>$ ls -lhS
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_lhS.png" alt=""></p><h4 id="_5-測量大小" tabindex="-1">5. 測量大小 <a class="header-anchor" href="#_5-測量大小" aria-label="Permalink to “5. 測量大小”">​</a></h4><p>ls可以通過使用<strong>-block-size=SIZE</strong>改單位大小。這裏的SIZE是：</p><pre><code>K = Kilobyte
M = Megabyte
G = Gigabyte
T = Terabyte
P = Petabyte
E = Exabyte
Z = Zettabyte
Y = Yottabyte
</code></pre><p>比如，我們希望使用MB作為單位大小。所以語法就會像這樣:</p><pre><code>$ ls -l --block-size=M
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_block_size.png" alt=""></p><h4 id="_6-顯示隱藏文件" tabindex="-1">6. 顯示隱藏文件 <a class="header-anchor" href="#_6-顯示隱藏文件" aria-label="Permalink to “6. 顯示隱藏文件”">​</a></h4><p>在Linux中，以&quot;.&quot;(<strong>點號</strong>)開頭的文件是隱藏文件。為了在ls命令中顯示它，我們可以使用<strong>-a</strong>選項。</p><pre><code>$ ls -a
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_a.png" alt=""></p><h4 id="_7-只列出目錄條目" tabindex="-1">7. 只列出目錄條目 <a class="header-anchor" href="#_7-只列出目錄條目" aria-label="Permalink to “7. 只列出目錄條目”">​</a></h4><p>如果我們希望只列出目錄，我們可以使用<strong>-d</strong>選項。</p><pre><code>$ ls -d */
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_d.png" alt=""></p><h4 id="_8-不打印所有者信息" tabindex="-1">8. 不打印所有者信息 <a class="header-anchor" href="#_8-不打印所有者信息" aria-label="Permalink to “8. 不打印所有者信息”">​</a></h4><p>要這麼做，我們使用<strong>-g</strong>選項。</p><pre><code>$ ls -g
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_lg.png" alt=""></p><h4 id="_9-不打印組信息" tabindex="-1">9. 不打印組信息 <a class="header-anchor" href="#_9-不打印組信息" aria-label="Permalink to “9. 不打印組信息”">​</a></h4><p>-g隱藏了擁有者信息，<strong>—G</strong>會隱藏組信息。</p><pre><code>$ ls -lG
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_lG2.png" alt=""></p><h4 id="_10-打印uid和gid" tabindex="-1">10. 打印UID和GID <a class="header-anchor" href="#_10-打印uid和gid" aria-label="Permalink to “10. 打印UID和GID”">​</a></h4><p>如果你想以數字方式列出項的所有者和所有組（即UID和GID），我們可以帶<strong>-n</strong>選項使用ls命令。這裏是個例子。</p><pre><code>$ ls -n
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_n.png" alt=""></p><p>從上面的例子中，我們知道<strong>用户pungki的UID</strong>是100，<strong>GID是1000</strong>，而<strong>root組的GID是0</strong>。</p><h4 id="_11-不帶顏色打印" tabindex="-1">11. 不帶顏色打印 <a class="header-anchor" href="#_11-不帶顏色打印" aria-label="Permalink to “11. 不帶顏色打印”">​</a></h4><p>一些Linux發行版已經對ls命令啓用彩色。這會使ls以各種顏色打印列表。如果你不想要這樣，你可以使用 <strong>--color=never</strong> 參數。</p><pre><code>$ ls --color=never
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_color_never.png" alt=""></p><h4 id="_12-打印每個文件的索引號" tabindex="-1">12. 打印每個文件的索引號 <a class="header-anchor" href="#_12-打印每個文件的索引號" aria-label="Permalink to “12. 打印每個文件的索引號”">​</a></h4><p>為了打印索引或者大家俗稱的inode號，我們可以使用-i選項。索引號會顯示在第一列。</p><pre><code>$ ls -li
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_inode.png" alt=""></p><h4 id="_13-增加-斜線-標記目錄" tabindex="-1">13. 增加 / (斜線) 標記目錄 <a class="header-anchor" href="#_13-增加-斜線-標記目錄" aria-label="Permalink to “13. 增加 / (斜線) 標記目錄”">​</a></h4><p>要這麼做，使用<strong>-p選項</strong>。</p><pre><code>$ ls -p
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_p.png" alt=""></p><h4 id="_14-排序時反轉順序" tabindex="-1">14. 排序時反轉順序 <a class="header-anchor" href="#_14-排序時反轉順序" aria-label="Permalink to “14. 排序時反轉順序”">​</a></h4><p>你或許需要在列出條目時反轉順序。要這麼做，你可以使用<strong>-r</strong>選項。</p><pre><code>$ ls -r
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_r.png" alt=""></p><h4 id="_15-遞歸列出子目錄" tabindex="-1">15. 遞歸列出子目錄 <a class="header-anchor" href="#_15-遞歸列出子目錄" aria-label="Permalink to “15. 遞歸列出子目錄”">​</a></h4><p>帶<strong>-R</strong>參數後，你可以列出包含它子目錄的目錄。</p><pre><code>$ ls -R
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_Recursive.png" alt=""></p><h4 id="_16-擴展名排序" tabindex="-1">16. 擴展名排序 <a class="header-anchor" href="#_16-擴展名排序" aria-label="Permalink to “16. 擴展名排序”">​</a></h4><p>你可以使用-X參數或者--sort=extension來通過擴展名來排序（譯註：這樣對於篩選不同類型的文件很有用）。</p><pre><code>$ ls -lX
</code></pre><p><strong>或</strong></p><pre><code>$ ls --sort=extension
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_x.png" alt=""></p><h4 id="_17-通過修改時間列出" tabindex="-1">17. 通過修改時間列出 <a class="header-anchor" href="#_17-通過修改時間列出" aria-label="Permalink to “17. 通過修改時間列出”">​</a></h4><p>使用-t選項會按修改時間排序，新的文件在前。</p><pre><code>$ ls -lt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_lt.png" alt=""></p><h4 id="_18-列出你的主目錄" tabindex="-1">18. 列出你的主目錄 <a class="header-anchor" href="#_18-列出你的主目錄" aria-label="Permalink to “18. 列出你的主目錄”">​</a></h4><p>要列出你的主目錄，你可以用&quot;~&quot;(<strong>波浪號</strong>)來代表它。這樣你就不必輸入完整的目錄名。讓我們假設家文件名為<strong>/home/pungki</strong>，那麼<strong>波浪號</strong>就對/home/pungki有意義了。</p><pre><code>$ ls ~
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_tilde.png" alt=""></p><h4 id="_19-列出父目錄" tabindex="-1">19. 列出父目錄 <a class="header-anchor" href="#_19-列出父目錄" aria-label="Permalink to “19. 列出父目錄”">​</a></h4><p>無論你在那個目錄，你可以列出父目錄而不必輸入完整路徑。這是個例子。</p><pre><code>$ ls ../
</code></pre><p>這回列出<strong>1</strong>層之上的目錄內容。</p><pre><code>$ ls ../../
</code></pre><p>這回列出<strong>2</strong>層之上的目錄內容（譯註：可不支持“...”來代表2層之上）。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_parent.png" alt=""></p><h4 id="_20-打印ls命令版本" tabindex="-1">20. 打印ls命令版本 <a class="header-anchor" href="#_20-打印ls命令版本" aria-label="Permalink to “20. 打印ls命令版本”">​</a></h4><p>使用--version參數打印它。</p><pre><code>$ ls --version
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_version.png" alt=""></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>這些是在日常操作中會使用到的參數。當然你總可以輸入<strong>man ls</strong> 或者 <strong>ls --help</strong> 來查詢ls的手冊頁</p><hr>`,100)),a("p",null,[e[1]||(e[1]=t("via: ",-1)),n(o,{href:"http://linoxide.com/linux-command/linux-ls-command/"},{default:l(()=>[...e[0]||(e[0]=[t("http://linoxide.com/linux-command/linux-ls-command/",-1)])]),_:1})]),a("p",null,[e[4]||(e[4]=t("譯者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:l(()=>[...e[2]||(e[2]=[t("geekpi",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:l(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),n(o,{href:"http://linux.cn/"},{default:l(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const P=r(c,[["render",h]]);export{k as __pageData,P as default};
